#!/usr/bin/env python3
"""Run C2 Unit09 recalibration with target-safe C2 length margin."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c2_unit09.py')
text=SOURCE.read_text(encoding='utf-8')
marker='UPDATES={'
assert text.count(marker)==1
EXTRA={
'ar-c2-u09-p02':"""وفي مراجعة أخيرة طلب المحلل من فريق مستقل اختيار القرار قبل أن يرى أسماء المسارات. كان عليهم ذكر أي افتراض إذا تغير سيقلب اختيارهم. اتفقوا على أن زمن الاستجابة وقابلية إضافة القدرة لاحقًا أهم من الاختلاف الصغير في متوسط الطلب. ثم كشفت لهم بيانات جديدة تؤثر في أحد الافتراضين فقط؛ عدلوا الجزء المرتبط به وتركوا بقية الحجة ثابتة. أظهر التمرين أن قيمة التفكير المستقبلي ليست في إنتاج قصص كثيرة، بل في جعل كل قصة مرتبطة بمقدمة يمكن تحديثها من دون إعادة كتابة منطق القرار كله بعد كل خبر.""",
'ar-c2-u09-p03':"""وفي اختبار إضافي أعطت الباحثة المراجعين حالات صحيحة كثيرة ثم أدخلت حالة خطأ نادرة. انخفض اكتشافها بعد سلسلة النجاح الطويلة، ما كشف أثر الاعتياد. عدلت المؤسسة الجدول بحيث تتخلل العمل اختبارات معروفة النتيجة وتظهر للمشرف بعد التنفيذ بوصفها مادة تدريبية. لم تستخدم الاختبارات لمعاقبة الأفراد، بل لقياس ما إذا كانت بنية المهمة تحافظ على الانتباه. كما قارنت الفرق بين مراجعة قرار قبل رؤية توصية الأداة وبعدها؛ عندما رأى الشخص التوصية أولًا زاد الميل إلى اتباعها. أضافوا لذلك مراجعة مستقلة لبعض الملفات الأعلى أثرًا قبل كشف اقتراح النظام.""",
'ar-c2-u09-p04':"""وفي مراجعة عمياء أعطت اللجنة مخطط المكونات لفريق جديد وطلبت منه تسمية المخاطر التي تقع بين الحدود. وجد الفريق أن كثيرًا من الأسئلة لا يملكها أي قسم: معنى مؤشر الثقة بعد التحويل، التأخير المقبول عبر السلسلة، وما الذي يحدث إذا تعارض تحديثان. أضيفت هذه الأسئلة إلى قائمة اختبار مشتركة قبل كل إصدار. لم يكن الهدف إنشاء قسم ضخم جديد، بل منع الحدود التنظيمية من أن تصبح حدودًا للانتباه. كل خطر عابر يحتاج إلى شخص يستطيع رؤيته من البداية إلى النهاية وإلى بيانات تسمح له بمعرفة أن العلاقة بين الأجزاء تغيرت.""",
'ar-c2-u09-p05':"""وفي تمرين أخير كتبت اللجنة ترتيبًا للالتزامات من الأسهل إلى الأصعب إلغاءً: تغيير إعداد، نقل مجموعة صغيرة، عقد قصير، عقد طويل، ثم تحويل بيانات قديمة بطريقة لا يمكن استعادتها بسهولة. طلبت من الفريق أن يثبت أن كل خطوة سابقة خفضت عدم اليقين الذي يبرر الانتقال إلى التالية. إذا لم تضف المرحلة الجديدة معرفة مرتبطة بالقرار، لا تكفي حقيقة أنها «نجحت» تشغيليًا. بهذه الطريقة صار التدرج وسيلة لجمع دليل له قيمة، لا سلسلة موافقات تلقائية تقود بحكم القصور الذاتي إلى التعميم الكامل.""",
'ar-c2-u09-p06':"""وفي نهاية الوحدة طلبت اللجنة من الطلاب كتابة سياسة قصيرة يمكن تطبيقها على تقنية مختلفة تمامًا. لم يسمح لهم بذكر نوع النموذج أو المنتج؛ كان عليهم استخدام أسئلة عامة عن من يختار، وما الذي يمكن الاعتراض عليه، وأين تقع الأخطاء النادرة، وكيف تتوزع القدرة على الإصلاح، وما الخطوة التي تغلق البدائل. نجحت السياسة عندما ظلت مفيدة بعد تغيير المجال لأن منطقها يصف بنية القرار لا خصائص أداة واحدة. ثم طلبت منهم ذكر حالة لا تكفي فيها هذه الأسئلة، فظهر أن بعض المشاريع تحتاج أيضًا إلى خبرة مجال أو قواعد قانونية خاصة. سجلوا ذلك كحد للمنهج بدل الادعاء بأنه بديل عن المعرفة المتخصصة.""",
}
extra_code="EXTRA = "+repr(EXTRA)+"\nfor _pid,_extra in EXTRA.items():\n    ADD[_pid]=ADD[_pid].rstrip()+' '+_extra.strip()\n"
patched=text.replace(marker,extra_code+'\n'+marker,1)
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
